// generar_285_analisis_agrupado_paseo_y_salud.js
// CHIQUI Entre Señales — Análisis reorganizado: bloque de Paseo con
// desplegables + sección Estado de salud unificada
//
// 1) BLOQUE DE PASEO (perros)
//    Quedan SIEMPRE visibles las dos tarjetas de un vistazo:
//      🔥 Racha de paseos   ·   🕒 Paseo en [mes]
//    Y los otros tres pasan a ser DESPLEGABLES independientes (cerrados
//    por defecto, se abre cada uno por separado):
//      📊 Tiempo de paseo por mes
//      📅 Actividad de la semana
//      📋 Detalle de [mes]
//    Así el bloque de paseo se ve limpio y ordenado, y el detalle está
//    a un toque cuando se quiere.
//
// 2) SECCIÓN "ESTADO DE SALUD"
//    Un encabezado agrupa visualmente los tres bloques que hablan de
//    cómo ha estado la mascota, que antes se veían sueltos:
//      · Lo observado este mes
//      · 📊 Normalidad por categoría
//      · Últimos 7 días
//    Se les dio continuidad (menos espacio entre ellos y sin
//    encabezados sueltos) para que se lean como un solo tema.
//
// NOTA sobre el mes: el título "Paseo en [mes]" usa el mes en curso
// calculado en vivo, así que el 1 de agosto cambiará solo a "Paseo en
// agosto" y el contador partirá de cero. No hay que hacer nada.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_285_analisis_agrupado_paseo_y_salud.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
